/* Validate the three-cluster solution using PROC DISCRIM */
proc discrim data=cluster_out
             crossvalidate
             pool=yes;
  class cluster;
  var Prin1 Prin2 Prin3;
  title "Discriminant Analysis - Validating Cluster Solution";
run;

/* Model 1: asset liquidation ~ financial monitoring x marital status */
proc logistic data=hardship;
  class married employed highestedu / param=ref;
  model finsoldpawn(event='1') = fcfinwatch married
                                 fcfinwatch*married
                                 age incomepos highestedu
                                 / lackfit rsquare;
  output out=pred p=predprob;
  title "Financial Monitoring x Marital Status - Asset Liquidation";
run;
